//! Game resources: Bytes, Floof, and Chips

use bevy::prelude::*;
use serde::{Deserialize, Serialize};

/// The three core currencies in Digital Dungeon Defense
#[derive(Resource, Default, Reflect, Serialize, Deserialize)]
#[reflect(Resource)]
pub struct PlayerResources {
    /// Passively generated by the core, used for resetting/repairing
    pub bytes: f32,
    /// Gathered from harming enemies, used for construction
    pub floof: f32,
    /// Dropped by intelligent invaders, used for dungeon levels
    pub chips: u32,

    /// Maximum byte storage capacity
    pub byte_capacity: f32,
    /// Core level affects byte generation rate
    pub core_level: u32,
}

impl PlayerResources {
    pub fn new() -> Self {
        Self {
            bytes: 100.0,
            floof: 50.0,
            chips: 0,
            byte_capacity: 500.0,
            core_level: 1,
        }
    }

    pub fn byte_generation_rate(&self) -> f32 {
        // Base rate * core level
        5.0 * self.core_level as f32
    }

    pub fn add_bytes(&mut self, amount: f32) {
        self.bytes = (self.bytes + amount).min(self.byte_capacity);
    }

    pub fn add_floof(&mut self, amount: f32) {
        self.floof += amount;
    }

    pub fn add_chips(&mut self, amount: u32) {
        self.chips += amount;
    }

    pub fn try_spend_bytes(&mut self, amount: f32) -> bool {
        if self.bytes >= amount {
            self.bytes -= amount;
            true
        } else {
            false
        }
    }

    pub fn try_spend_floof(&mut self, amount: f32) -> bool {
        if self.floof >= amount {
            self.floof -= amount;
            true
        } else {
            false
        }
    }

    pub fn try_spend_chips(&mut self, amount: u32) -> bool {
        if self.chips >= amount {
            self.chips -= amount;
            true
        } else {
            false
        }
    }
}

/// Event fired when resources are gained
#[derive(Event)]
pub struct ResourceGainEvent {
    pub bytes: f32,
    pub floof: f32,
    pub chips: u32,
}

/// System that passively generates bytes based on core level
pub fn passive_byte_generation_system(
    mut resources: ResMut<PlayerResources>,
    time: Res<Time>,
) {
    let rate = resources.byte_generation_rate();
    resources.add_bytes(rate * time.delta_secs());
}
